<?php $title='My profile';require 'includes/header.php';require_login();$q=$pdo->prepare('SELECT * FROM users WHERE id=?');$q->execute([$_SESSION['user']['id']]);$u=$q->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['profile'])){$q=$pdo->prepare('UPDATE users SET name=?,phone=?,address=? WHERE id=?');$q->execute([trim($_POST['name']),trim($_POST['phone']),trim($_POST['address']),$u['id']]);$_SESSION['user']['name']=trim($_POST['name']);$_SESSION['flash']='Profile updated.';}if(isset($_POST['password'])&&password_verify($_POST['current_password']??'',$u['password'])&&strlen($_POST['new_password']??'')>=8){$pdo->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),$u['id']]);$_SESSION['flash']='Password changed.';}header('Location: '.url('profile.php'));exit;} ?>
<h1 class="section-title mb-4">My profile</h1><div class="row g-4"><div class="col-md-7"><div class="card p-4 border-0 shadow-sm"><h5>Personal details</h5><form method="post" class="row g-3 mt-1"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="col-12"><label class="form-label">Name</label><input class="form-control" name="name" value="<?=e($u['name'])?>"></div><div class="col-md-6"><label class="form-label">Email</label><input disabled class="form-control" value="<?=e($u['email'])?>"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=e($u['phone'])?>"></div><div class="col-12"><label class="form-label">Address</label><textarea name="address" class="form-control"><?=e($u['address'])?></textarea></div><button name="profile" class="btn btn-primary col-auto ms-2 rounded-pill">Save changes</button></form></div></div><div class="col-md-5"><div class="card p-4 border-0 shadow-sm"><h5>Change password</h5><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input class="form-control mb-2" type="password" name="current_password" placeholder="Current password"><input class="form-control mb-3" minlength="8" type="password" name="new_password" placeholder="New password (8+ characters)"><button name="password" class="btn btn-outline-primary rounded-pill">Update password</button></form></div></div></div><?php require 'includes/footer.php'; ?>
